import React, { useState, useEffect } from "react"
import { supabase } from "./supabaseClient"
import DonateModal from "./DonateModal"
import { NAVY, GOLD, GOLD2, WHITE, MGRAY, RED, GREEN, LGRAY, Logo } from "./constants"

const STARS_LOGO = "data:image/png;base64,"
const GB_LOGO    = "data:image/png;base64,"

const OPP_LOGOS = {
  "Golden Birds": GB_LOGO,
  "GOLDEN BIRDS": GB_LOGO,
}

const ROAD_FALLBACK = [
  { opp:"White Staff",       score:"0-1", result:"L", venue:"Away" },
  { opp:"Letlhakane United", score:"2-0", result:"W", venue:"Away" },
  { opp:"Mmatshumo Classic", score:"0-2", result:"L", venue:"Away" },
  { opp:"Stone Breakers",    score:"1-0", result:"W", venue:"Away" },
  { opp:"Mighty Birds",      score:"0-2", result:"L", venue:"Away" },
]

const ForYouScreen = ({ session, openMembership, setActiveTab }) => {
  const [news,       setNews]       = useState([])
  const [fixtures,   setFixtures]   = useState([])
  const [showDonate, setShowDonate] = useState(false)
  const [countdown,  setCountdown]  = useState(null)

  useEffect(()=>{
    supabase.from("news").select("*").eq("published",true)
      .order("created_at",{ascending:false}).limit(10)
      .then(({data})=>{ if(data) setNews(data) })
    supabase.from("fixtures").select("*").order("match_date",{ascending:true})
      .then(({data})=>{ if(data) setFixtures(data) })
  },[])

  const nextFixture = fixtures.find(f=>!f.result && new Date(f.match_date+'T12:00:00') >= new Date())
    || { match_date:"2026-05-23", kick_off:"13:30", opponent:"Golden Birds", venue:"HOME" }

  useEffect(()=>{
    const tick = () => {
      try {
        const [yr,mo,dy] = nextFixture.match_date.split("-").map(Number)
        const [hh,mm]    = (nextFixture.kick_off||"13:30").split(":").map(Number)
        const matchTime  = new Date(yr, mo-1, dy, hh, mm, 0)
        const diff       = matchTime - new Date()
        if(diff <= 0){ setCountdown(null); return }
        setCountdown({
          d: Math.floor(diff/86400000),
          h: Math.floor((diff%86400000)/3600000),
          m: Math.floor((diff%3600000)/60000),
          s: Math.floor((diff%60000)/1000),
        })
      } catch(e){ setCountdown(null) }
    }
    tick()
    const id = setInterval(tick, 1000)
    return ()=>clearInterval(id)
  },[nextFixture?.match_date])

  const Box = ({val,label}) => (
    <div style={{textAlign:"center"}}>
      <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:900,
        fontSize:"clamp(22px,6vw,30px)",color:GOLD,lineHeight:1,
        background:"rgba(255,255,255,0.1)",borderRadius:8,padding:"4px 8px",minWidth:44}}>
        {String(val).padStart(2,"0")}
      </div>
      <div style={{fontSize:"clamp(8px,2vw,9px)",color:"rgba(255,255,255,0.6)",
        marginTop:3,fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,
        letterSpacing:"0.08em"}}>{label}</div>
    </div>
  )

  const roadData = fixtures.filter(f=>f.result).slice(-5).length > 0
    ? fixtures.filter(f=>f.result).slice(-5).map(f=>({
        opp:f.opponent, score:`${f.score_us}-${f.score_them}`,
        result:f.result, venue:f.venue
      }))
    : ROAD_FALLBACK

  const oppLogo = OPP_LOGOS[nextFixture?.opponent]

  return (
    <div style={{flex:1,overflowY:"auto",WebkitOverflowScrolling:"touch",background:"#f5f6fa"}}>
      {showDonate&&<DonateModal onClose={()=>setShowDonate(false)} session={session}/>}

      {/* NEXT MATCH */}
      <div style={{background:`linear-gradient(160deg,${NAVY},#1a3060)`,
        padding:"clamp(14px,4vw,20px) clamp(14px,4vw,18px)",position:"relative",overflow:"hidden"}}>
        <div style={{opacity:0.06,position:"absolute",right:-20,top:-20,pointerEvents:"none"}}>
          <Logo size={180}/>
        </div>
        <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:800,
          fontSize:10,color:GOLD,letterSpacing:"0.14em",marginBottom:8}}>NEXT MATCH</div>

        {/* Teams */}
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",
          marginBottom:10,gap:8}}>
          <div style={{display:"flex",flexDirection:"column",alignItems:"center",gap:5,flex:1}}>
            <img src={STARS_LOGO} alt="90 Stars"
              style={{width:"clamp(44px,12vw,58px)",height:"clamp(44px,12vw,58px)",
                objectFit:"contain",borderRadius:"50%",
                background:"rgba(255,255,255,0.08)",padding:2}}/>
            <span style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:900,
              fontSize:"clamp(9px,2.5vw,11px)",color:WHITE,textAlign:"center"}}>90 STARS</span>
          </div>
          <div style={{display:"flex",flexDirection:"column",alignItems:"center",gap:2}}>
            <span style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:900,
              fontSize:"clamp(14px,4vw,20px)",color:GOLD}}>VS</span>
            <span style={{fontSize:8,color:"rgba(255,255,255,0.45)",
              fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700}}>WEEK 24</span>
          </div>
          <div style={{display:"flex",flexDirection:"column",alignItems:"center",gap:5,flex:1}}>
            <div style={{width:"clamp(44px,12vw,58px)",height:"clamp(44px,12vw,58px)",
              borderRadius:"50%",background:"rgba(255,255,255,0.08)",
              display:"flex",alignItems:"center",justifyContent:"center",
              overflow:"hidden",padding:2}}>
              {oppLogo
                ? <img src={oppLogo} alt={nextFixture.opponent}
                    style={{width:"100%",height:"100%",objectFit:"contain"}}/>
                : <span style={{fontSize:24}}>⚽</span>}
            </div>
            <span style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:900,
              fontSize:"clamp(9px,2.5vw,11px)",color:WHITE,textAlign:"center",
              maxWidth:"clamp(70px,20vw,100px)",overflow:"hidden",
              textOverflow:"ellipsis",whiteSpace:"nowrap"}}>
              {(nextFixture.opponent||"").toUpperCase()}
            </span>
          </div>
        </div>

        {/* Match info */}
        <div style={{fontSize:"clamp(10px,2.5vw,11px)",color:"rgba(255,255,255,0.6)",
          marginBottom:10,display:"flex",gap:8,flexWrap:"wrap",alignItems:"center"}}>
          <span>📅 {new Date(nextFixture.match_date+'T12:00:00').toLocaleDateString("en-GB",
            {weekday:"short",day:"numeric",month:"short"})}</span>
          <span>⏰ {nextFixture.kick_off||"13:30"}</span>
          <span>📍 Falcon Ground</span>
          <span style={{background:GREEN,color:WHITE,padding:"1px 6px",borderRadius:3,
            fontSize:9,fontWeight:800,fontFamily:"'Barlow Condensed',sans-serif"}}>HOME</span>
        </div>

        {/* Countdown */}
        {countdown ? (
          <div style={{display:"flex",gap:"clamp(6px,2vw,10px)",alignItems:"center"}}>
            <Box val={countdown.d} label="DAYS"/>
            <span style={{color:"rgba(255,255,255,0.4)",fontWeight:900,fontSize:22,marginBottom:14}}>:</span>
            <Box val={countdown.h} label="HRS"/>
            <span style={{color:"rgba(255,255,255,0.4)",fontWeight:900,fontSize:22,marginBottom:14}}>:</span>
            <Box val={countdown.m} label="MINS"/>
            <span style={{color:"rgba(255,255,255,0.4)",fontWeight:900,fontSize:22,marginBottom:14}}>:</span>
            <Box val={countdown.s} label="SECS"/>
            <div style={{marginLeft:"auto"}}>
              <div onClick={()=>setActiveTab&&setActiveTab("calendar")}
                style={{background:GOLD,color:NAVY,borderRadius:8,padding:"8px 12px",
                  fontFamily:"'Barlow Condensed',sans-serif",fontWeight:900,
                  fontSize:11,letterSpacing:"0.06em",textAlign:"center",cursor:"pointer"}}>
                MATCH<br/>CENTER
              </div>
            </div>
          </div>
        ) : (
          <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:900,
            fontSize:16,color:GOLD,textAlign:"center",padding:"8px 0"}}>
            🕐 KICK OFF TODAY AT {nextFixture.kick_off||"13:30"}
          </div>
        )}
      </div>

      {/* QUICK ACTIONS */}
      <div style={{padding:"10px 12px 0",display:"flex",gap:8,overflowX:"auto",
        WebkitOverflowScrolling:"touch"}}>
        {[
          {icon:"🎟",label:"TICKETS",  fn:()=>setActiveTab&&setActiveTab("store")},
          {icon:"👕",label:"SHOP",     fn:()=>setActiveTab&&setActiveTab("store")},
          {icon:"❤️",label:"DONATE",   fn:()=>setShowDonate(true)},
          {icon:"📰",label:"NEWS",     fn:null},
          {icon:"🦡",label:"MEMBERS",  fn:openMembership},
        ].map(item=>(
          <button key={item.label} onClick={item.fn||undefined}
            style={{flexShrink:0,display:"flex",flexDirection:"column",alignItems:"center",
              gap:4,padding:"8px 12px",background:WHITE,border:"1.5px solid #eee",
              borderRadius:12,cursor:item.fn?"pointer":"default",minWidth:60,
              WebkitTapHighlightColor:"transparent",boxShadow:"0 1px 4px rgba(0,0,0,0.06)"}}>
            <span style={{fontSize:20}}>{item.icon}</span>
            <span style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:800,
              fontSize:9,color:NAVY,letterSpacing:"0.06em"}}>{item.label}</span>
          </button>
        ))}
      </div>

      {/* ROAD TO TOP 8 */}
      <div style={{padding:"14px 12px 0"}}>
        <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:900,
          fontSize:"clamp(14px,4vw,17px)",color:NAVY,marginBottom:10,
          display:"flex",alignItems:"center",gap:8}}>
          🏆 ROAD TO TOP 8
          <span style={{fontSize:11,color:MGRAY,fontWeight:600}}>· Season 2025/26</span>
        </div>
        <div style={{display:"flex",gap:10,overflowX:"auto",paddingBottom:4,
          WebkitOverflowScrolling:"touch"}}>
          {roadData.map((r,i)=>{
            const win  = r.result==="W"
            const draw = r.result==="D"
            return (
              <div key={i} style={{flexShrink:0,display:"flex",flexDirection:"column",
                alignItems:"center",gap:5}}>
                <div style={{width:"clamp(52px,14vw,62px)",height:"clamp(52px,14vw,62px)",
                  borderRadius:"50%",
                  border:`3px solid ${win?GOLD:draw?"#888":RED}`,
                  background:win?`${GOLD}18`:draw?"#f0f0f0":"#fef2f2",
                  display:"flex",flexDirection:"column",
                  alignItems:"center",justifyContent:"center",
                  position:"relative",overflow:"hidden"}}>
                  <img src={STARS_LOGO} alt="" style={{position:"absolute",inset:0,
                    width:"100%",height:"100%",objectFit:"cover",opacity:0.12}}/>
                  <span style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:900,
                    fontSize:"clamp(11px,3vw,14px)",
                    color:win?GOLD2:draw?MGRAY:RED,lineHeight:1,zIndex:1}}>
                    {r.score}
                  </span>
                  <span style={{fontSize:8,color:win?"#555":draw?"#888":"#c0392b",
                    fontWeight:700,zIndex:1}}>
                    {win?"WIN":draw?"DRAW":"LOSS"}
                  </span>
                </div>
                <span style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,
                  fontSize:"clamp(8px,2vw,9px)",color:MGRAY,textAlign:"center",
                  maxWidth:64,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>
                  {r.opp}
                </span>
                <span style={{fontSize:8,color:MGRAY,fontWeight:600}}>{r.venue}</span>
              </div>
            )
          })}
          {/* NEXT — Golden Birds */}
          <div style={{flexShrink:0,display:"flex",flexDirection:"column",alignItems:"center",gap:5}}>
            <div style={{width:"clamp(52px,14vw,62px)",height:"clamp(52px,14vw,62px)",
              borderRadius:"50%",border:`3px dashed ${GOLD}`,
              background:`${NAVY}18`,
              display:"flex",alignItems:"center",justifyContent:"center",overflow:"hidden"}}>
              <img src={GB_LOGO} alt="Golden Birds"
                style={{width:"85%",height:"85%",objectFit:"contain"}}/>
            </div>
            <span style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:700,
              fontSize:"clamp(8px,2vw,9px)",color:NAVY,textAlign:"center",maxWidth:64,
              overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>
              Golden Birds
            </span>
            <span style={{fontSize:8,color:GOLD2,fontWeight:800,
              fontFamily:"'Barlow Condensed',sans-serif"}}>NEXT ⚽</span>
          </div>
        </div>
      </div>

      {/* DONATE BANNER */}
      <div style={{margin:"12px 12px 0"}}>
        <div onClick={()=>setShowDonate(true)}
          style={{background:`linear-gradient(135deg,${RED},#922b21)`,
            borderRadius:14,padding:"14px 16px",cursor:"pointer",
            display:"flex",alignItems:"center",justifyContent:"space-between",
            WebkitTapHighlightColor:"transparent",
            boxShadow:"0 4px 14px rgba(192,57,43,0.3)"}}>
          <div>
            <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:900,
              fontSize:"clamp(14px,4vw,18px)",color:WHITE,lineHeight:1}}>
              ❤️ SUPPORT THE HONEY BADGERS
            </div>
            <div style={{fontSize:"clamp(11px,3vw,13px)",color:"rgba(255,255,255,0.75)",marginTop:4}}>
              Every pula helps the team grow
            </div>
          </div>
          <div style={{background:WHITE,color:RED,borderRadius:8,padding:"8px 14px",
            fontFamily:"'Barlow Condensed',sans-serif",fontWeight:900,
            fontSize:"clamp(11px,3vw,13px)",flexShrink:0}}>DONATE →</div>
        </div>
      </div>

      {/* NEWS */}
      <div style={{padding:"14px 12px 20px"}}>
        <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:900,
          fontSize:"clamp(14px,4vw,17px)",color:NAVY,marginBottom:10}}>📰 LATEST NEWS</div>
        {news.length===0 ? (
          <div style={{textAlign:"center",padding:24,color:MGRAY,fontSize:13,
            background:WHITE,borderRadius:12}}>No news yet. Check back soon!</div>
        ) : (
          <div style={{display:"flex",flexDirection:"column",gap:10}}>
            {news.map((n,i)=>(
              <div key={n.id} style={{background:WHITE,borderRadius:14,overflow:"hidden",
                boxShadow:"0 1px 6px rgba(0,0,0,0.07)"}}>
                <div style={{height:4,background:i===0?GOLD:i===1?GREEN:NAVY}}/>
                <div style={{padding:"12px 14px"}}>
                  <div style={{display:"flex",alignItems:"center",gap:6,marginBottom:6}}>
                    <span style={{background:NAVY,color:GOLD,fontSize:9,fontWeight:900,
                      padding:"2px 7px",borderRadius:4,
                      fontFamily:"'Barlow Condensed',sans-serif"}}>{n.tag||"NEWS"}</span>
                    <span style={{fontSize:11,color:MGRAY}}>
                      {new Date(n.created_at).toLocaleDateString("en-GB",{day:"numeric",month:"short"})}
                    </span>
                  </div>
                  <div style={{fontFamily:"'Barlow Condensed',sans-serif",fontWeight:900,
                    fontSize:"clamp(14px,4vw,17px)",color:NAVY,lineHeight:1.2,marginBottom:6}}>
                    {n.title}
                  </div>
                  {n.summary&&(
                    <div style={{fontSize:"clamp(12px,3vw,13px)",color:MGRAY,lineHeight:1.6,
                      display:"-webkit-box",WebkitLineClamp:2,
                      WebkitBoxOrient:"vertical",overflow:"hidden"}}>{n.summary}</div>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  )
}

export default ForYouScreen
